import os
from openai import OpenAI

def invoke_model(prompt: str, model_name: str = "gpt-4o"):
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
        organization=os.environ.get("OPENAI_ORGANIZATION_ID")
    )

    response = client.chat.completions.create(
        model=model_name,
        messages=[
            {"role": "user", "content": prompt}
        ]
    )
    return response.choices[0].message.content

import os
from openai import OpenAI

def stream_model_generation(prompt: str, model_name: str = "gpt-4o"):
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
        organization=os.environ.get("OPENAI_ORGANIZATION_ID")
    )

    stream = client.chat.completions.create(
        model=model_name,
        messages=[
            {"role": "user", "content": prompt}
        ],
        stream=True,
    )

    for chunk in stream:
        if chunk.choices[0].delta.content is not None:
            yield chunk.choices[0].delta.content

import os
from openai import OpenAI

def collect_generation_with_metadata(prompt: str, model_name: str = "gpt-4o"):
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
        organization=os.environ.get("OPENAI_ORGANIZATION_ID")
    )

    response = client.chat.completions.create(
        model=model_name,
        messages=[
            {"role": "user", "content": prompt}
        ],
        stream=False,
    )

    content = response.choices[0].message.content
    metadata = {
        "model": response.model,
        "id": response.id,
        "usage": response.usage.model_dump() if response.usage else None, # usage might be None in some cases
        "openai_object": response.object
    }

    return content, metadata

import os
from openai import OpenAI
from google.cloud import aiplatform

class ModelClient:
    def __init__(self, provider: str):
        self.provider = provider
        self._client = None

    def get_client(self):
        if self._client:
            return self._client

        if self.provider == "openai":
            self._client = OpenAI(
                api_key=os.environ.get("OPENAI_API_KEY"),
                organization=os.environ.get("OPENAI_ORGANIZATION_ID")
            )
        elif self.provider == "google_vertex_ai":
            # For Vertex AI, client initialization often involves project and location
            # and specific services (e.g., aiplatform.gapic.PredictionServiceClient)
            # For simplicity, we'll just initialize the AIPlatform client here.
            project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
            location = os.environ.get("GOOGLE_CLOUD_LOCATION")
            if project_id and location:
                aiplatform.init(project=project_id, location=location)
            self._client = aiplatform
        else:
            raise ValueError(f"Unsupported provider: {self.provider}")
        return self._client

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

@dataclass
class Message:
    role: str
    content: str

@dataclass
class ModelRequest:
    messages: List[Message]
    model: str
    temperature: Optional[float] = 0.7
    max_tokens: Optional[int] = 150

@dataclass
class ModelResponse:
    id: str
    model: str
    created: int
    choices: List[Dict[str, Any]]
    usage: Dict[str, Any]
    provider: str = "unknown"

def normalize_openai_response(response: Any) -> ModelResponse:
    """Normalizes an OpenAI API response into a common ModelResponse format."""
    return ModelResponse(
        id=response.id,
        model=response.model,
        created=response.created,
        choices=[choice.model_dump() for choice in response.choices],
        usage=response.usage.model_dump() if response.usage else {},
        provider="openai"
    )
